INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47511, 'Exodus 12:12', 'Exodus', 12, 12, 'په هغه شپه به زه په مصر باندې تېرېږم او هر لومړنی زېږېدلی انسان او حیوان به ووژنم او د مصر ټولو خدایانو ته به سزا ورکړم. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_12.mp3', '', 1761754199, 1761754199),
(47512, 'Exodus 12:13', 'Exodus', 12, 13, 'هغه وینه چې ستاسو د کورونو د دروازو په سرونو او د چوکاټونو په دواړو خواوو باندې وي، هغه به ستاسو د کورونو نښې وي او کله چې زه هغه ووینم، نو ستاسو د کورونو څخه به تېرېږم او یوازې مصریان به وژنم او تاسو ته به هېڅ زیان نه رسوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_13.mp3', '', 1761754199, 1761754199),
(47513, 'Exodus 12:14', 'Exodus', 12, 14, 'تاسو باید دا ورځ د اختر په توګه ولمانځئ، ترڅو دا تاسو ته در په یاد کړي چې ما یعنې څښتن ستاسو دپاره کوم کارونه کړي دي. دا به د ټولو راتلونکو وختونو دپاره لمانځئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_14.mp3', '', 1761754199, 1761754199),
(47514, 'Exodus 12:15', 'Exodus', 12, 15, 'څښتن وویل: «تاسو باید اووه ورځې فطیره ډوډۍ وخورئ. په لومړۍ ورځ ټوله خمیره د خپلو کورونو څخه لېرې کړئ، ځکه که چېرې څوک په هغو اووه ورځو کې خمیره ډوډۍ وخوري هغه به زما د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_15.mp3', '', 1761754199, 1761754199),
(47515, 'Exodus 12:16', 'Exodus', 12, 16, 'په لومړۍ او اوومه ورځ تاسو د عبادت دپاره سره راټول شئ. په هغو ورځو کې د ډوډۍ د تیارولو څخه پرته بل کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_16.mp3', '', 1761754199, 1761754199),
(47516, 'Exodus 12:17', 'Exodus', 12, 17, 'دا اختر ولمانځئ، ځکه چې دا هماغه ورځ ده چې ما ستاسو قبیلې له مصر څخه راوویستلې. تاسو باید دا ورځ د یو اختر په توګه د تل دپاره ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_17.mp3', '', 1761754199, 1761754199),
(47517, 'Exodus 12:18', 'Exodus', 12, 18, 'د اولې میاشتې د څوارلسم ماښام څخه نیولې د یوویشتمې ورځې تر ماښامه پورې باید تاسو فطیره ډوډۍ وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_18.mp3', '', 1761754199, 1761754199),
(47518, 'Exodus 12:19', 'Exodus', 12, 19, 'اووه ورځې باید ستاسو په کورونو کې خمیره پیدا نه شي. ځکه که چېرې څوک که هغه پردی وي او یا اسراییلی وي خمیره ډوډۍ وخوري، هغه به د اسراییلو د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_19.mp3', '', 1761754199, 1761754199),
(47519, 'Exodus 12:20', 'Exodus', 12, 20, 'هېڅ داسې شی مه خورئ چې د خمیرې څخه تیار شوی وي. هر چېرته چې تاسو اوسېږئ باید فطیره ډوډۍ وخورئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_20.mp3', '', 1761754199, 1761754199),
(47520, 'Exodus 12:21', 'Exodus', 12, 21, 'بیا موسی د اسراییلو ټول مشران راوغوښتل او ورته ویې ویل: «لاړ شئ او د خپلو کورنیو دپاره د رمو څخه وري او وزې واخلئ او د فسحې د اختر دپاره یې حلال کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_21.mp3', '', 1761754199, 1761754199),
(47521, 'Exodus 12:22', 'Exodus', 12, 22, 'د وېلني د بوټو یوه غونچه واخلئ او په هغې وینه کې یې غوټه کړئ چې په لوښي کې ده او د خپلو کورونو د دروازو د چوکاټ په دواړو خواو او پورتنۍ برخې باندې یې وشیندئ. هېڅوک به د خپل کور څخه تر سهاره پورې نه وځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_22.mp3', '', 1761754199, 1761754199),
(47522, 'Exodus 12:23', 'Exodus', 12, 23, 'کله چې څښتن د مصریانو د وژلو دپاره د مصر څخه تېریږي، هغه به د دروازو په چوکاټونو او د دروازو په پورتنیو برخو وینه وویني او د مرګ فرښته به پرېنږدي چې ستاسو کورونو ته ستاسو د وژلو دپاره ورننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_23.mp3', '', 1761754199, 1761754199),
(47523, 'Exodus 12:24', 'Exodus', 12, 24, 'تاسو او ستاسو اولادونه باید د تل دپاره په دې اصولو باندې عمل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_24.mp3', '', 1761754199, 1761754199),
(47524, 'Exodus 12:25', 'Exodus', 12, 25, 'کله چې تاسو هغې ځمکې ته چې څښتن یې تاسو ته د ورکولو وعده کړې ده ورننوځئ، باید دا مراسم هلته سرته ورسوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_25.mp3', '', 1761754199, 1761754199),
(47525, 'Exodus 12:26', 'Exodus', 12, 26, 'کله چې ستاسو ماشومان ستاسو څخه پوښتنه وکړي چې د دې مراسمو معنی څه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_26.mp3', '', 1761754199, 1761754199),
(47526, 'Exodus 12:27', 'Exodus', 12, 27, 'تاسو به په ځواب کې ووایئ: دا د فسحې د اختر قرباني ده چې د څښتن د درناوي دپاره یې کوو، ځکه چې هغه شپه چې څښتن په مصر کې د اسراییلیانو د کورونو دپاسه تېر شو، هغه مصریان ووژل، خو مونږ یې ژوندي پرېښودلو.» بیا قوم په سجده شو او عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_27.mp3', '', 1761754199, 1761754199),
(47527, 'Exodus 12:28', 'Exodus', 12, 28, 'بیا هغوی لاړل او څنګه چې څښتن موسی او هارون ته حکم کړی ؤ، هماغسې یې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_28.mp3', '', 1761754199, 1761754199),
(47528, 'Exodus 12:29', 'Exodus', 12, 29, 'په نیمه شپه کې څښتن په مصر کې ټول مشران زامن ووژل. د فرعون د زوی څخه نیولې چې د تخت وارث ؤ د بندي تر مشر زوی پورې چې په زندان کې ؤ او د ټولو حیواناتو لومړني بچیان یې هم ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_29.mp3', '', 1761754199, 1761754199),
(47529, 'Exodus 12:30', 'Exodus', 12, 30, 'فرعون، د هغه ټول درباریان او مصریان د شپې راویښ شول او په مصر کې سخته ژړا او انګولا وه، ځکه چې هلته داسې کور نه ؤ چې مړی په کې نه ؤ شوی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_30.mp3', '', 1761754199, 1761754199),
(47530, 'Exodus 12:31', 'Exodus', 12, 31, 'په هماغه شپه فرعون موسی او هارون راوغوښتل او ورته ویې ویل: «د خپلو خلکو سره ووځئ! زما خاوره پرېږدئ. لاړ شئ او لکه څرنګه چې تاسو غوښتل د څښتن عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_31.mp3', '', 1761754199, 1761754199),
(47531, 'Exodus 12:32', 'Exodus', 12, 32, 'خپلې رمې او پادې هم د ځان سره بوځئ او لاړ شئ. او ماته هم برکت راکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_32.mp3', '', 1761754199, 1761754199),
(47532, 'Exodus 12:33', 'Exodus', 12, 33, 'مصریانو د اسراییلو قوم وهڅاوه چې د هغه هېواد څخه زر لاړ شي. هغوی وویل: «که چېرې تاسو لاړ نه شئ، نو مونږ ټول به مړه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_33.mp3', '', 1761754199, 1761754199),
(47533, 'Exodus 12:34', 'Exodus', 12, 34, 'نو اسرایلیانو بې خمیرې اوړه په لګنونو کې واچول، په ټوکرونو کې یې تاو کړل او په خپلو اوږو یې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_34.mp3', '', 1761754199, 1761754199),
(47534, 'Exodus 12:35', 'Exodus', 12, 35, 'اسراییلیانو د موسی په لارښوونې عمل وکړ او د مصریانو څخه یې د سرو او سپینو زرو شیان او کالي وغوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_35.mp3', '', 1761754199, 1761754199),
(47535, 'Exodus 12:36', 'Exodus', 12, 36, 'څښتن اسراییلیان د مصریانو په نظر کې عزتمن کړل او هرڅه یې چې د مصریانو څخه غوښتل، نو هغوی به ورکول. په دې ډول اسراییلیانو د مصریانو شتمني د ځان سره یووړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_36.mp3', '', 1761754199, 1761754199),
(47536, 'Exodus 12:37', 'Exodus', 12, 37, 'اسراییلیانو له رعمسیس څخه سوکوت ته په پښو سفر وکړ. د ښځو او ماشومانو څخه پرته د سړیو شمېر نژدې شپږ سوه زره تنو ته رسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_37.mp3', '', 1761754199, 1761754199),
(47537, 'Exodus 12:38', 'Exodus', 12, 38, 'ډېر نور خلک هم د هغوی سره لاړل او هغوی سره خپلې رمې او پادې هم وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_38.mp3', '', 1761754199, 1761754199),
(47538, 'Exodus 12:39', 'Exodus', 12, 39, 'هغوی د هغو اوړو څخه فطیره ډوډۍ پخه کړه چې د مصر څخه یې راوړي وو او هغوی وخت نه درلود چې د ځان دپاره خمیره ډوډۍ یا نور خواړه تیار کړي، ځکه چې ناڅاپه له مصر څخه شړل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_39.mp3', '', 1761754199, 1761754199),
(47539, 'Exodus 12:40', 'Exodus', 12, 40, 'اسراییلیان څلور سوه دېرش کاله په مصر کې اوسېدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_40.mp3', '', 1761754199, 1761754199),
(47540, 'Exodus 12:41', 'Exodus', 12, 41, 'په هماغه ورځ چې څلور سوه دېرش کاله پوره شول، د څښتن د قوم ټولې قبیلې د مصر څخه ووتلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_41.mp3', '', 1761754199, 1761754199),
(47541, 'Exodus 12:42', 'Exodus', 12, 42, 'دا هغه شپه وه چې څښتن په هغوی باندې پام کاوه چې هغوی له مصر څخه راوباسي. همدا شپه د څښتن دپاره وقف شوه، په دې خاطر باید د اسراییلو راتلونکي نسلونه د تل دپاره دا شپه د څښتن دپاره د یادګار په توګه ولمانځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_42.mp3', '', 1761754199, 1761754199),
(47542, 'Exodus 12:43', 'Exodus', 12, 43, 'څښتن موسی او هارون ته وویل: «دا د فسحې د اختر اصول دي: هېڅ پردی سړی باید د فسحې د اختر خواړه ونه خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_43.mp3', '', 1761754199, 1761754199),
(47543, 'Exodus 12:44', 'Exodus', 12, 44, 'خو کوم غلام چې تاسو په بیه اخیستی وي او سنت شوی وي هغه کولای شي چې دا خواړه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_44.mp3', '', 1761754199, 1761754199),
(47544, 'Exodus 12:45', 'Exodus', 12, 45, 'هېڅ موقتي اوسېدونکی یا مزدور دې هغه ونه خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_45.mp3', '', 1761754199, 1761754199),
(47545, 'Exodus 12:46', 'Exodus', 12, 46, 'ټول خواړه باید په هغه کور کې دننه وخوړل شي چې په کې تیار شوي دي او غوښه د کور څخه دباندې مه راوباسئ. یو هډوکی هم مات نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_46.mp3', '', 1761754199, 1761754199),
(47546, 'Exodus 12:47', 'Exodus', 12, 47, 'د اسراییلو ټول قوم باید دا اختر ولمانځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_47.mp3', '', 1761754199, 1761754199),
(47547, 'Exodus 12:48', 'Exodus', 12, 48, 'کوم سړی چې سنت شوی نه وي هغه دې دا ونه خوري. که چېرې کوم پردی سړی په تاسو کې اوسیږي او غواړي چې د څښتن د درناوي دپاره د فسحې اختر ولمانځي، تاسو باید لومړی د هغه د کورنۍ ټول نران سنت کړئ. بیا به د هغه سره لکه د یو اصلي اسراییلي په شان چلند کیږي او کولای شي چې په دې اختر کې برخه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_48.mp3', '', 1761754199, 1761754199),
(47548, 'Exodus 12:49', 'Exodus', 12, 49, 'په اصلي اسراییلي او هغو پردیو خلکو باندې چې ستاسو په منځ کې اوسیږي باید یوشان اصول عملي شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_49.mp3', '', 1761754199, 1761754199),
(47549, 'Exodus 12:50', 'Exodus', 12, 50, 'ټولو اسراییلیانو د څښتن په حکم باندې چې په موسی او هارون باندې یې کړی ؤ، عمل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_50.mp3', '', 1761754199, 1761754199),
(47550, 'Exodus 12:51', 'Exodus', 12, 51, 'په هماغه ورځ څښتن د اسراییلو قبیلې د مصر څخه راوویستلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_51.mp3', '', 1761754199, 1761754199),
(47551, 'Exodus 25:1', 'Exodus', 25, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_1.mp3', '', 1761754199, 1761754199),
(47552, 'Exodus 25:2', 'Exodus', 25, 2, '«اسراییلیانو ته ووایه چې ماته یوه نذرانه راوړي. ته باید زما دپاره د هغه چا څخه نذرانه واخلې چې زړه یې غواړي وریې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_2.mp3', '', 1761754199, 1761754199),
(47553, 'Exodus 25:3', 'Exodus', 25, 3, 'دا هغه نذرانې دي چې ته یې باید د هغوی څخه واخلې: سره زر، سپین زر او برنج،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_3.mp3', '', 1761754199, 1761754199),
(47554, 'Exodus 25:4', 'Exodus', 25, 4, 'ښه کتان، ابي، بانجاني او سرې وړۍ، هغه ټوکر چې د وزو د وړیو څخه جوړ شوی وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_4.mp3', '', 1761754199, 1761754199),
(47555, 'Exodus 25:5', 'Exodus', 25, 5, 'سره رنګ شوي د پسه پوستکي، ښه څرمن، د اکاسۍ لرګی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_5.mp3', '', 1761754199, 1761754199),
(47556, 'Exodus 25:6', 'Exodus', 25, 6, 'د څراغونو دپاره تېل، د مسح کولو د تېلو او د خوشبویۍ دپاره مواد،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_6.mp3', '', 1761754199, 1761754199),
(47557, 'Exodus 25:7', 'Exodus', 25, 7, 'عقیق او نورې قیمتي تیږې چې د لوی کاهن په سپېڅلي پېشبند او د هغه په سینه پوښ باندې ولګول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_7.mp3', '', 1761754199, 1761754199),
(47558, 'Exodus 25:8', 'Exodus', 25, 8, 'بیا په خلکو باندې زما دپاره یوه سپېڅلې خېمه جوړه کړه، ترڅو وکولای شم د هغوی په منځ کې واوسېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_8.mp3', '', 1761754199, 1761754199),
(47559, 'Exodus 25:9', 'Exodus', 25, 9, 'دا خېمه او د هغې ټول سامان کټ مټ د هغې نقشې له مخې جوړ کړه چې زه یې درته ښایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_9.mp3', '', 1761754199, 1761754199),
(47560, 'Exodus 25:10', 'Exodus', 25, 10, 'په هغوی باندې د اکاسۍ د لرګي څخه یو صندوق جوړ کړه چې یو متر او لس سانتي اوږد وي، پنځه شپېته سانتي پلن وي او پنځه شپېته سانتي لوړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_10.mp3', '', 1761754199, 1761754199),
(47561, 'Exodus 25:11', 'Exodus', 25, 11, 'د هغه منځنۍ او باندېنۍ برخې ته د سوچه سرو زرو پوښ ورکړه او ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_11.mp3', '', 1761754199, 1761754199),
(47562, 'Exodus 25:12', 'Exodus', 25, 12, 'د هغه دپاره څلور د سرو زرو کړۍ ګانې جوړې کړه او هغه په څلورو پایو باندې وتړه، یعنې دوه کړۍ ګانې په یوې خوا او دوه په بلې خوا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_12.mp3', '', 1761754199, 1761754199),
(47563, 'Exodus 25:13', 'Exodus', 25, 13, 'د صندوق د وړلو دپاره د اکاسۍ د لرګي څخه دوه میلې جوړې کړه او د سرو زرو پوښ ورته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_13.mp3', '', 1761754199, 1761754199),
(47564, 'Exodus 25:14', 'Exodus', 25, 14, 'هغه میلې هغو کړیو ته چې د صندوق په څنګونو کې دي، ورننباسه ترڅو صندوق ورباندې یووړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_14.mp3', '', 1761754199, 1761754199),
(47565, 'Exodus 25:15', 'Exodus', 25, 15, 'میلې دې په کړیو کې پاتې شي او هغه باید راونه ویستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_15.mp3', '', 1761754199, 1761754199),
(47566, 'Exodus 25:16', 'Exodus', 25, 16, 'بیا به د تیږو هغه دوه لوحې چې حکمونه ورباندې لیکل شوي دي، درکړم چې هغه په صندوق کې کېږدې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_16.mp3', '', 1761754199, 1761754199),
