(47568, 'Exodus 25:18', 'Exodus', 25, 18, 'د سرپوښ په دواړو خواوو باندې د ټکول شویو سرو زرو څخه دوه اسماني مخلوقات جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_18.mp3', '', 1761754199, 1761754199),
(47569, 'Exodus 25:19', 'Exodus', 25, 19, 'یو یې په یوې خوا او دوهم یې په بلې خوا باندې جوړ کړه. په دوو خواوو باندې د سرپوښ سره اسماني مخلوقات د سرو زرو د یوې ټوټې څخه جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_19.mp3', '', 1761754199, 1761754199),
(47570, 'Exodus 25:20', 'Exodus', 25, 20, 'د اسماني مخلوقاتو وزرونه دې پورته خپاره شوي وي چې په سرپوښ باندې سیوری وکړي. مخلوقات دې یو بل ته مخامخ وي او د سرپوښ خواته دې ګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_20.mp3', '', 1761754199, 1761754199),
(47571, 'Exodus 25:21', 'Exodus', 25, 21, 'په صندوق کې د تیږو دوه لوحې کېږده او هغه سرپوښ د صندوق دپاسه کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_21.mp3', '', 1761754199, 1761754199),
(47572, 'Exodus 25:22', 'Exodus', 25, 22, 'زه به د سرپوښ دپاسه د دوو مخلوقاتو ترمنځ چې د لوظ په صندوق باندې دي، ستا سره لیدنه کتنه وکړم او د اسراییلو د قوم دپاره به خپل ټول حکمونه درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_22.mp3', '', 1761754199, 1761754199),
(47573, 'Exodus 25:23', 'Exodus', 25, 23, 'د اکاسۍ د لرګي څخه یو داسې مېز جوړ کړه چې نوي سانتي اوږد وي، پنځه څلوېښت سانتي پلن وي او پنځه شپېته سانتي لوړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_23.mp3', '', 1761754199, 1761754199),
(47574, 'Exodus 25:24', 'Exodus', 25, 24, 'هغه ته د سوچه سرو زرو پوښ ورکړه او د هغه ګردچاپېره څنډې د سرو زرو څخه جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_24.mp3', '', 1761754199, 1761754199),
(47575, 'Exodus 25:25', 'Exodus', 25, 25, 'همدارنګه د هغه ګردچاپېره یو چوکاټ جوړ کړه چې پراخوالی یې نیمه لوېشت وي او په چوکاټ باندې د سرو زرو څنډې جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_25.mp3', '', 1761754199, 1761754199),
(47576, 'Exodus 25:26', 'Exodus', 25, 26, 'د مېز دپاره څلور د سرو زرو کړۍ ګانې جوړې کړه او په هغو څلورو کنجونو کې چېرته چې څلور پایې دي وتړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_26.mp3', '', 1761754199, 1761754199),
(47577, 'Exodus 25:27', 'Exodus', 25, 27, 'کړۍ ګانې دې چوکاټ ته نژدې وي، د دې دپاره چې هغه میلې ونیسي چې د مېز په وړلو کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_27.mp3', '', 1761754199, 1761754199),
