(47588, 'Exodus 25:38', 'Exodus', 25, 38, 'د هغه پلته پاکوونکي او پتنوسونه دې د سوچه سرو زرو وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_38.mp3', '', 1761754199, 1761754199),
(47589, 'Exodus 25:39', 'Exodus', 25, 39, 'د څراغدان او د هغه د ټول سامان په جوړولو کې د څلوردېرشو کیلو ګرامه سوچه سرو زرو څخه کار واخله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_39.mp3', '', 1761754199, 1761754199),
(47590, 'Exodus 25:40', 'Exodus', 25, 40, 'دې خبرې ته پام وکړه چې دا د هغې نمونې له مخې جوړ کړې چې ما درته د غره په سر باندې دروښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus25_verse_40.mp3', '', 1761754199, 1761754199),
(47591, 'Numbers 30:1', 'Numbers', 30, 1, 'موسی د اسراییلو د قبیلو مشرانو ته د څښتن دغه حکمونه ورکړل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_1.mp3', '', 1761754199, 1761754199),
(47592, 'Numbers 30:2', 'Numbers', 30, 2, '«کله چې یو سړی څښتن ته یو شی نذر ورکوي، یا داسې قسم وخوري چې د ځینو شیانو څخه به ځان لېرې ساتي، نو هغه باید خپله وعده ماته نه کړي، بلکې څه چې یې ویلي دي هغه دې سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_2.mp3', '', 1761754199, 1761754199),
(47593, 'Numbers 30:3', 'Numbers', 30, 3, 'که چېرې یوه پېغله چې د خپل پلار په کور کې اوسیږي، څښتن ته کوم شی نذر ورکوي یا داسې وعده کوي چې د ځینو شیانو څخه به ځان لېرې ساتي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_3.mp3', '', 1761754199, 1761754199),
(47594, 'Numbers 30:4', 'Numbers', 30, 4, 'که چېرې د هغې پلار د هغې څخه خبر شي او څه ونه وایي، نو هغه باید خپل نذر ورکړي یا خپله وعده پوره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_4.mp3', '', 1761754199, 1761754199),
(47595, 'Numbers 30:5', 'Numbers', 30, 5, 'خو که چېرې د هغې پلار د هغې څخه خبر شي او هغه د نذر ورکولو څخه منع کړي، هغه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. څښتن به هغه وبخښي، ځکه چې پلار یې منع کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_5.mp3', '', 1761754199, 1761754199),
(47596, 'Numbers 30:8', 'Numbers', 30, 8, 'خو که چېرې د هغې مېړه ورڅخه خبر شي او هغه د نذر د پوره کولو څخه منع کړي، نو هغه ښځه د خپلې وعدې په پوره کولو باندې مجبوره نه ده. څښتن به هغه وبخښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_8.mp3', '', 1761754199, 1761754199),
(47597, 'Numbers 30:9', 'Numbers', 30, 9, 'کونډې او طلاق شوې ښځې باید هر هغه نذر او یا خپله وعده سرته ورسوي چې څښتن سره یې کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_9.mp3', '', 1761754199, 1761754199),
(47598, 'Numbers 30:10', 'Numbers', 30, 10, 'فرض کړئ یوه واده شوې ښځه څښتن ته یو نذر ومني او یا کومه وعده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_10.mp3', '', 1761754199, 1761754199),
(47599, 'Numbers 30:11', 'Numbers', 30, 11, 'که چېرې د هغې مېړه ورڅخه خبر شي او څه ونه وایي، نو هغې ښځې چې کومه وعده کړې یا هر نذر چې هغې منلی وي باید هغه سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_11.mp3', '', 1761754199, 1761754199),
(47600, 'Numbers 30:12', 'Numbers', 30, 12, 'خو که چېرې د هغې مېړه خبر شي او هغه د نذر د پوره کولو څخه منع کړي، نو هغه یې په سرته رسولو مجبوره نه ده. څښتن به هغه وبخښي، ځکه چې مېړه یې د نذر پوره کولو څخه منع کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_12.mp3', '', 1761754199, 1761754199),
(47601, 'Numbers 30:13', 'Numbers', 30, 13, 'د هغې مېړه دا حق لري چې کوم نذر هغې منلی دی او یا یې کومه وعده کړې ده، هغه تایید او یا رد کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_13.mp3', '', 1761754199, 1761754199),
(47602, 'Numbers 30:14', 'Numbers', 30, 14, 'که چېرې د هغې مېړه په هماغه ورځ د نذر څخه خبر شي او څه ونه وایي، نو د هر شي نذر چې هغې منلی وي او یا یې وعده کړې وي هغه باید سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_14.mp3', '', 1761754199, 1761754199),
(47603, 'Numbers 30:15', 'Numbers', 30, 15, 'خو که چېرې د هغې مېړه دا نذر وروسته رد کړي، نو د هغې ګناه به د هغه په غاړه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_15.mp3', '', 1761754199, 1761754199),
(47604, 'Numbers 30:16', 'Numbers', 30, 16, 'دا هغه قوانین دي چې څښتن موسی ته د هغو نذرونو په اړه ورکړل چې د پېغلو له خوا چې د پلار په کور کې اوسیږي، ورکول کیږي او د هغو ښځو له خوا چې واده شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers30_verse_16.mp3', '', 1761754199, 1761754199),
(47605, 'Proverbs 18:1', 'Proverbs', 18, 1, 'ځان غوښتونکی انسان د خلکو نه ځان لېرې ساتي او تل د حکمت مخالفت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_1.mp3', '', 1761754199, 1761754199),
(47606, 'Proverbs 18:2', 'Proverbs', 18, 2, 'کم‌عقل سړی د پوهې سره مینه نه لري او یوازې د خپل نظر په څرګندولو خوشحالیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_2.mp3', '', 1761754199, 1761754199),
(47607, 'Proverbs 18:3', 'Proverbs', 18, 3, 'کله چې شرارت راشي نو رسوایي هم راځي او شرم او سپکاوی هم ورسره ملګري وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_3.mp3', '', 1761754199, 1761754199),
(47608, 'Proverbs 18:4', 'Proverbs', 18, 4, 'د انسان د خولې خبرې د ژورې څاه اوبه دي د حکمت چینه د تنګې درې روان خوړ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_4.mp3', '', 1761754199, 1761754199),
(47609, 'Proverbs 18:5', 'Proverbs', 18, 5, 'دا ښه کار نه دی چې د مجرم طرفداري دې وشي او یا د بې‌ګناه حق تر‌پښو لاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_5.mp3', '', 1761754199, 1761754199),
(47610, 'Proverbs 18:6', 'Proverbs', 18, 6, 'د کم‌عقل خبرې جنجالونه جوړوي او خوله یې وهلو ته بلنه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_6.mp3', '', 1761754199, 1761754199);